const CACHE='biuno-a5072165d12c';const FILES=["/","/styles.css","/redesign.css","/tokens.css","/favicon.svg","/manifest.webmanifest","/assets/app.mjs","/assets/game.mjs","/assets/engine.mjs","/assets/storage.mjs","/assets/art.mjs","/assets/i18n.mjs","/en/","/en/matching-pairs/","/en/what-changed/","/en/sequence-memory/","/en/codebreaker/","/en/pipes/","/en/mental-math/","/en/imprint/","/en/privacy/","/en/progress/","/de/","/de/matching-pairs/","/de/what-changed/","/de/sequence-memory/","/de/codebreaker/","/de/pipes/","/de/mental-math/","/de/imprint/","/de/privacy/","/de/progress/","/cs/","/cs/matching-pairs/","/cs/what-changed/","/cs/sequence-memory/","/cs/codebreaker/","/cs/pipes/","/cs/mental-math/","/cs/imprint/","/cs/privacy/","/cs/progress/","/pl/","/pl/matching-pairs/","/pl/what-changed/","/pl/sequence-memory/","/pl/codebreaker/","/pl/pipes/","/pl/mental-math/","/pl/imprint/","/pl/privacy/","/pl/progress/"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('biuno-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('message',e=>{if(e.data==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin)return;e.respondWith(caches.match(e.request,{ignoreSearch:true}).then(hit=>hit||fetch(e.request)));});
